{"function":"() => {
// list focusable sequence via tabbable heuristic (light + shadow)
const res=[];
function walk(root){ for (const el of root.querySelectorAll('*')) { if (el.shadowRoot) walk(el.shadowRoot); if (el.matches('a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]')) { const r=el.getBoundingClientRect(); if (r.width>0 && el.tabIndex>=0) res.push((el.tagName+' '+(el.getAttribute('aria-label')||el.textContent.trim()).slice(0,30))); } } }
walk(document);
return res.slice(0,40);
}"}

